const ASSETS = new Map([{"path":"/index.html","contentType":"text/html; charset=utf-8","base64":""},{"path":"/Alkhansae_CV_2026_PDF.pdf","contentType":"application/pdf","base64":""},{"path":"/WhatsApp Image 2025-06-07 à 12.37.23_bd4a3f26.jpg","contentType":"image/jpeg","base64":""}].map((asset) => [
  asset.path,
  asset,
]));

const PDF_FILENAME = "Alkhansae_CV_2026_PDF.pdf";
const CANONICAL_PATH = "/cv-dr-alkhansae";

function toBytes(base64) {
  const bin = atob(base64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function assetResponse(asset) {
  const headers = {
    "content-type": asset.contentType,
    "cache-control": "public, max-age=3600",
  };

  if (asset.path.endsWith(".pdf")) {
    headers["content-disposition"] = 'attachment; filename="' + PDF_FILENAME + '"';
  }

  return new Response(toBytes(asset.base64), {
    headers,
  });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const pathname = decodeURIComponent(url.pathname);

    if (pathname === "/") {
      return Response.redirect(new URL(CANONICAL_PATH, url), 302);
    }

    if (pathname === CANONICAL_PATH) {
      return assetResponse(ASSETS.get("/index.html"));
    }

    if (ASSETS.has(pathname)) {
      return assetResponse(ASSETS.get(pathname));
    }

    return assetResponse(ASSETS.get("/index.html"));
  },
};
